{"code": "from rdkit import Chem
from rdkit.Chem import Descriptors, AllChem, DataStructs

start = "CCOC(=O)c1ccc2c(c1)NC(=O)C2"
tad = "CN1CC(=O)N2[C@H](c3ccc4c(c3)OCO4)C3=C(CCN(C3=O)Cc3ccccc3)c3[nH]c4ccccc4c32"  # tadalafil approx
sil = "CCCN1CCN(CC1)S(=O)(=O)c1cc(ccc1OCC)C1=NC(=O)c2cc(ccc2N1C)OCC"  # sildenafil approx

for name, smi in [("start", start), ("tad", tad), ("sil", sil)]:
    m = Chem.MolFromSmiles(smi)
    print(name, m is not None, Chem.MolToSmiles(m) if m else None)
    if m:
        print("  MW", round(Descriptors.MolWt(m),1), "HBD", Descriptors.NumHDonors(m), "HBA", Descriptors.NumHAcceptors(m), "rings", Descriptors.RingCount(m), "logP", round(Descriptors.MolLogP(m),2))"}
